mieterhoehung_sonderkuendigungsfenster <- function(zugang_erhoehungsmitteilung_am=NULL, verlangter_erhoehungsbeginn_am=NULL, kuendigungseingang_am=NULL, einordnungsnachweis=NULL) {
 zugang <- .datum(zugang_erhoehungsmitteilung_am,'zugang_erhoehungsmitteilung_am');erhoehung <- .datum(verlangter_erhoehungsbeginn_am,'verlangter_erhoehungsbeginn_am');kuendigung <- .datum(kuendigungseingang_am,'kuendigungseingang_am');.text(einordnungsnachweis,'einordnungsnachweis')
 grund <- .frist(paste0(substr(zugang_erhoehungsmitteilung_am,1,7),'-01'),3,'monate','tagesbeginn')
 if(substr(verlangter_erhoehungsbeginn_am,9,10)!='01' || erhoehung<=grund) .fehler('verlangter_erhoehungsbeginn_am','Monatserster nicht vor regul\u00e4rem Erh\u00f6hungsbeginn erforderlich.')
 letzt <- .tage_addieren(erhoehung,-1);ende <- .frist(verlangter_erhoehungsbeginn_am,2,'monate','tagesbeginn')
 wert <- list(regulaerer_letzter_erklaerungstag=.iso(grund),letzter_erklaerungstag_bei_verlangtem_beginn=.iso(letzt),mietende_bei_voller_fristausnutzung=.iso(ende),erklaerung_im_zeitfenster=zugang<=kuendigung && kuendigung<=letzt)
 eingaben <- list(zugang_erhoehungsmitteilung_am=zugang_erhoehungsmitteilung_am, verlangter_erhoehungsbeginn_am=verlangter_erhoehungsbeginn_am, kuendigungseingang_am=kuendigungseingang_am, einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,"daten_und_wahrheitswert","BGB_MIETERHOEHUNG_SONDERKUENDIGUNGSFENSTER",eingaben,list(list(operation="Aus\u00fcbungsgrundfrist und bei sp\u00e4ter verlangter Erh\u00f6hung verl\u00e4ngertes Erkl\u00e4rungsfenster sowie Mietende bei voller Fristausnutzung berechnen.")),eingaben)
 ergebnis$hinweise <- list("\u00a7561I mit\u00a7558bI; sp\u00e4tere verlangte Erh\u00f6hung nach BGH25.9.2013,VIII ZR280/12,Rn17\u201318. Regul\u00e4re Aus\u00fcbungsgrundfrist endet am letzten Tag des zweiten Folgemonats; bei sp\u00e4ter verlangter Erh\u00f6hung bleibt die Erkl\u00e4rung bis zum Vortag des Erh\u00f6hungsbeginns m\u00f6glich. Mietende bei voller Ausnutzung: Ende des zweiten mit Erh\u00f6hungsbeginn beginnenden Kalendermonats. Dieses Datum ist der bei voller Fristausnutzung erreichbare Termin, nicht automatisch das tats\u00e4chliche Ende jeder fr\u00fcheren oder anders formulierten K\u00fcndigung. Der zeitliche Eingangsvergleich best\u00e4tigt keine \u00fcbrige Wirksamkeit. Bei wirksamer561K\u00fcndigung bleibt die bisherige Miete ma\u00dfgeblich; diese Rechtsfolge ist keine zus\u00e4tzliche eigenst\u00e4ndige Zahlenformel. Sonderkorrekturen des Zugangs/\u00a7193 gesondert, keine automatische Verschiebung der erkl\u00e4rten Termine.")
 ergebnis
}
